static uint16_t ceph_fscache_inode_get_aux ( const void * cookie_netfs_data , void * buffer , uint16_t bufmax ) { struct ceph_aux_inode aux ; const struct ceph_inode_info * ci = cookie_netfs_data ; const struct inode * inode = & ci -> vfs_inode ; aux . version = ci -> i_version ; aux . mtime = inode -> i_mtime ; aux . size = i_size_read ( inode ) ; memcpy ( buffer , & aux , sizeof ( aux ) ) ; return sizeof ( aux ) ; } 